"""Self-contained actual-motion playback; no network or browser dependencies."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
scenes=json.loads((OUT/'scenario_expectations.json').read_text());data=[]
for scene in scenes:
 rows=json.loads((OUT/'candidate_31'/(scene['name']+'_trace.json')).read_text())
 result=json.loads((OUT/'candidate_31'/(scene['name']+'_result.json')).read_text())
 data.append({'scene':scene,'result':result,'rows':[{k:r[k] for k in ('t','x','y','yaw','v','mode','ready','reason','gap')} for r in rows]})
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><meta charset="utf-8"><title>三模式闭环实验回放</title><style>body{font:16px system-ui;margin:30px;background:#f5f7fa;color:#1f2937}main{max-width:1100px;margin:auto}select,button{font:inherit;padding:8px;border:1px solid #cad1dc;border-radius:7px;background:white}canvas{width:100%;background:white;border:1px solid #dce1e9;border-radius:12px}input{width:65%}p{line-height:1.6}.meta{padding:12px;background:white;border-radius:8px}</style><main><h1>三模式闭环实验回放</h1><p>本地仿真实际积分轨迹；含3秒模式等待、C++驱动策略与0.25秒模拟worker交付延迟。不是实车测试。绿色ACK，蓝色CRAB，紫色SPIN。灰色为障碍物；对向目标按场景速度继续运动。</p><select id="scene"></select> <button id="play">播放/暂停</button> <input id="time" type="range" min="0" value="0"><p class="meta" id="meta"></p><canvas id="canvas" width="1100" height="530"></canvas><p id="expected"></p><p>未到达场景完整保留。U形退出和原前方目标到达是两个不同结果。详细统计与归因见REPORT.md。</p></main><script>const DATA=PAYLOAD;let index=0,frame=0,playing=false;const sel=document.querySelector('#scene'),slider=document.querySelector('#time'),ctx=document.querySelector('#canvas').getContext('2d');const colors={0:'#247c62',1:'#217bb4',4:'#8b56a4'};DATA.forEach((d,i)=>{const o=document.createElement('option');o.value=i;o.textContent=d.scene.name;sel.append(o)});function draw(){let d=DATA[index],r=d.rows[frame],xmin=Math.min(-4,...d.rows.map(p=>p.x-1)),xmax=6;let scale=Math.min(1000/(xmax-xmin),440/4.6),ox=60-xmin*scale,oy=265;let X=x=>ox+x*scale,Y=y=>oy-y*scale;ctx.clearRect(0,0,1100,530);ctx.strokeStyle='#79828d';[-2,2].forEach(y=>{ctx.beginPath();ctx.moveTo(X(xmin),Y(y));ctx.lineTo(X(xmax),Y(y));ctx.stroke()});function box(x,y,a,l,w,color,fill){ctx.save();ctx.translate(X(x),Y(y));ctx.rotate(-a);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.globalAlpha=fill?.4:1;if(fill)ctx.fillRect(-l*scale/2,-w*scale/2,l*scale,w*scale);ctx.strokeRect(-l*scale/2,-w*scale/2,l*scale,w*scale);ctx.restore()}d.scene.objects.forEach(o=>box(o.x+o.vx*r.t,o.y+o.vy*r.t,o.heading,o.length,o.width,'#8b929d',true));for(let i=1;i<=frame;i++){let a=d.rows[i-1],b=d.rows[i];ctx.strokeStyle=colors[a.mode];ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(X(a.x),Y(a.y));ctx.lineTo(X(b.x),Y(b.y));ctx.stroke()}ctx.lineWidth=2;box(r.x,r.y,r.yaw,1.2,.8,colors[r.mode],false);ctx.beginPath();ctx.moveTo(X(r.x),Y(r.y));ctx.lineTo(X(r.x+.6*Math.cos(r.yaw)),Y(r.y+.6*Math.sin(r.yaw)));ctx.stroke();ctx.fillStyle='#df9e22';ctx.beginPath();ctx.arc(X(d.scene.goal[0]),Y(d.scene.goal[1]),7,0,Math.PI*2);ctx.fill();document.querySelector('#meta').textContent=`t=${r.t.toFixed(1)}s · 模式=${r.mode} · READY=${r.ready} · v=${r.v.toFixed(3)}m/s · 净距=${r.gap.toFixed(3)}m · ${r.reason} · 本次${d.result.reached?'到达':'未达'}，总时间${d.result.duration_s}s`;document.querySelector('#expected').textContent='测试前预期：'+d.scene.expected;slider.value=frame}sel.onchange=()=>{index=+sel.value;frame=0;slider.max=DATA[index].rows.length-1;draw()};slider.oninput=()=>{frame=+slider.value;draw()};document.querySelector('#play').onclick=()=>playing=!playing;setInterval(()=>{if(playing){frame=Math.min(frame+1,DATA[index].rows.length-1);draw();if(frame===DATA[index].rows.length-1)playing=false}},80);slider.max=DATA[0].rows.length-1;draw();</script>'''.replace('PAYLOAD',payload)
(OUT/'playback.html').write_text(html)
print('Saved self-contained playback.html')
